"""
cot_service.py – CFTC Commitments of Traders data helper.
Fetches only new reports from publicreporting.cftc.gov and caches them in CotReport.
The full market list (1300+ products) is fetched dynamically from the CFTC API
and cached locally so the sidebar always shows all available markets.
"""
import datetime
import logging
import os
import json
import requests
from django.db import transaction
from .models import CotReport

logger = logging.getLogger(__name__)

CFTC_API_URL = "https://publicreporting.cftc.gov/resource/6dca-aqww.json"

# Path to cached full market list (regenerated by Sync All Markets)
_CACHE_DIR = os.path.dirname(os.path.abspath(__file__))
MARKETS_CACHE_FILE = os.path.join(_CACHE_DIR, "cftc_markets_cache.json")

