# ── Group-keyword mapping for auto-classification ─────────────────────────────
_GROUP_KEYWORDS = {
    "AGRICULTURE": [
        "corn", "soy", "wheat", "oat", "rice", "cattle", "hogs", "pork", "bacon",
        "coffee", "sugar", "cocoa", "cotton", "orange", "lumber", "milk", "butter",
        "cheese", "dry milk", "feeder", "broiler", "potato", "barley", "palm",
        "rapeseed", "canola", "euronext",
    ],
    "METALS": [
        "gold", "silver", "copper", "palladium", "platinum", "aluminum",
        "steel", "iron", "zinc", "nickel", "lead", "tin",
    ],
    "ENERGY": [
        "crude", "oil", "gas", "gasoline", "heating", "propane", "rbob",
        "ethanol", "diesel", "fuel", "brent", "wti", "coal", "power",
        "electricity", "carbon", "lng",
    ],
}


def _infer_group(name: str) -> str:
    """Guess commodity group from market name keywords."""
    lower = name.lower()
    for group, keywords in _GROUP_KEYWORDS.items():
        if any(kw in lower for kw in keywords):
            return group
    return "FINANCIAL INSTRUMENTS"


# ─────────────────────────────────────────────────────────────────────────────
# Cache helpers
# ─────────────────────────────────────────────────────────────────────────────

def _load_cached_markets() -> list[dict]:
    """Load full market list from the local JSON cache, or return []."""
    if os.path.exists(MARKETS_CACHE_FILE):
        try:
            with open(MARKETS_CACHE_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as exc:
            logger.warning("Could not read markets cache: %s", exc)
    return []


def _save_cached_markets(markets: list[dict]) -> None:
    """Persist the market list to local JSON cache."""
    try:
        with open(MARKETS_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(markets, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        logger.warning("Could not save markets cache: %s", exc)


def fetch_all_available_markets() -> tuple[list[dict], int]:
    """
    Query the CFTC API for the full distinct list of available FutOnly markets.
    Saves to local cache and returns (market_list, new_count).
    """
    params = {
        '$select': 'cftc_contract_market_code,market_and_exchange_names,commodity_group_name',
        '$where': "futonly_or_combined='FutOnly'",
        '$group': 'cftc_contract_market_code,market_and_exchange_names,commodity_group_name',
        '$limit': 5000,
    }
    resp = requests.get(CFTC_API_URL, params=params, timeout=60)
    resp.raise_for_status()
    rows = resp.json()

    markets = []
    seen = set()
    for r in rows:
        code = r.get('cftc_contract_market_code', '').strip()
        name = r.get('market_and_exchange_names', '').strip()
        group = (r.get('commodity_group_name') or '').strip().upper() or _infer_group(name)
        key = (code, name)
        if code and name and key not in seen:
            seen.add(key)
            markets.append({'code': code, 'name': name, 'group': group})

    markets.sort(key=lambda m: (m['group'], m['name']))
    _save_cached_markets(markets)
    return markets, len(markets)


# ─────────────────────────────────────────────────────────────────────────────
# Public API
# ─────────────────────────────────────────────────────────────────────────────

def _parse_int(v, default=0):
    try:
        return int(float(v or default))
    except (ValueError, TypeError):
        return default


def get_available_markets():
    """Return distinct (market_code, market_name) saved in the DB, alphabetically."""
    return (
        CotReport.objects
        .values('market_code', 'market_name', 'commodity_group')
        .distinct()
        .order_by('market_name')
    )


def get_latest_saved_date(market_code: str):
    """Return the most recent report_date saved for a given market_code, or None."""
    row = CotReport.objects.filter(market_code=market_code).order_by('-report_date').first()
    return row.report_date if row else None


def fetch_and_save_cot(market_code: str, limit: int = 5000) -> int:
    """
    Fetch legacy futures-only COT records for `market_code` from CFTC API.
    Only downloads records newer than what is already stored.
    Returns number of new rows saved.
    """
    latest = get_latest_saved_date(market_code)
    params = {
        '$where': f"cftc_contract_market_code='{market_code}' AND futonly_or_combined='FutOnly'",
        '$order': 'report_date_as_yyyy_mm_dd ASC',
        '$limit': limit,
    }
    if latest:
        after = (latest + datetime.timedelta(days=1)).isoformat()
        params['$where'] += f" AND report_date_as_yyyy_mm_dd >= '{after}'"

    try:
        resp = requests.get(CFTC_API_URL, params=params, timeout=30)
        resp.raise_for_status()
        rows = resp.json()
    except Exception as exc:
        logger.error("CFTC API error for %s: %s", market_code, exc)
        raise

    saved = 0
    with transaction.atomic():
        for r in rows:
            date_str = r.get('report_date_as_yyyy_mm_dd', '')[:10]
            if not date_str:
                continue
            try:
                report_date = datetime.date.fromisoformat(date_str)
            except ValueError:
                continue

            obj, created = CotReport.objects.update_or_create(
                report_date=report_date,
                market_code=market_code,
                defaults=dict(
                    market_name=r.get('market_and_exchange_names', ''),
                    commodity_name=r.get('commodity_name', ''),
                    commodity_group=r.get('commodity_group_name', ''),
                    open_interest=_parse_int(r.get('open_interest_all')),
                    noncomm_long=_parse_int(r.get('noncomm_positions_long_all')),
                    noncomm_short=_parse_int(r.get('noncomm_positions_short_all')),
                    noncomm_spread=_parse_int(r.get('noncomm_postions_spread_all')),
                    comm_long=_parse_int(r.get('comm_positions_long_all')),
                    comm_short=_parse_int(r.get('comm_positions_short_all')),
                    nonrept_long=_parse_int(r.get('nonrept_positions_long_all')),
                    nonrept_short=_parse_int(r.get('nonrept_positions_short_all')),
                ),
            )
            if created:
                saved += 1

    return saved


def get_grouped_markets() -> dict:
    """
    Return markets grouped by commodity_group for the sidebar.

    Priority:
    1. Full market list from local cache (fetch_all_available_markets builds this)
    2. Markets already saved in the DB
    3. Hard-coded DEFAULT_MARKETS as last resort
    """
    # Short name deduplication set per group to prevent "CORN - CME" vs "CORN" duplicates
    groups: dict[str, dict[str, dict]] = {}  # group -> {code -> {code, name}}
    seen_names_per_group: dict[str, set[str]] = {}

    # 1. Load from local cache (full CFTC list)
    cached = _load_cached_markets()
    for m in cached:
        g = (m.get('group') or 'Other').upper()
        code = m['code']
        # Use short name (before hyphen)
        short_name = m['name'].split('-')[0].strip()
        display_name = short_name if short_name else m['name']
        upper_name = display_name.upper()
        
        seen = seen_names_per_group.setdefault(g, set())
        if upper_name not in seen:
            seen.add(upper_name)
            groups.setdefault(g, {})[code] = {'code': code, 'name': display_name}

    # 2. Supplement with any DB-stored markets (e.g. already synced data)
    for m in get_available_markets():
        g = (m['commodity_group'] or 'Other').upper()
        code = m['market_code']
        short_name = m['market_name'].split('-')[0].strip()
        display_name = short_name if short_name else m['market_name']
        upper_name = display_name.upper()

        seen = seen_names_per_group.setdefault(g, set())
        if upper_name not in seen:
            seen.add(upper_name)
            groups.setdefault(g, {})[code] = {'code': code, 'name': display_name}

    # 3. Fall back to DEFAULT_MARKETS if nothing loaded yet
    if not groups:
        for code, name in DEFAULT_MARKETS:
            g = _infer_group(name).upper()
            groups.setdefault(g, {})[code] = {'code': code, 'name': name}

    # Sort groups and items within each group
    return {
        gname: sorted(groups[gname].values(), key=lambda x: x['name'])
        for gname in sorted(groups.keys())
    }


def get_chart_data(market_code: str) -> dict:
    """
    Returns data for charting:
    1. time_series: list of {date, noncomm_net, comm_net, nonrept_net, open_interest}
    2. seasonality_weekly: {week: {avg_noncomm_net, ...}}
    3. seasonality_monthly: {month: {avg_noncomm_net, ...}}
    """
    qs = (
        CotReport.objects
        .filter(market_code=market_code)
        .order_by('report_date')
        .values(
            'report_date', 'year', 'week_of_year',
            'noncomm_long', 'noncomm_short',
            'comm_long', 'comm_short',
            'nonrept_long', 'nonrept_short',
            'open_interest',
        )
    )

    time_series = []
    wk_acc: dict[int, list] = {}
    mo_acc: dict[int, list] = {}

    for row in qs:
        nc_net = row['noncomm_long'] - row['noncomm_short']
        cm_net = row['comm_long'] - row['comm_short']
        nr_net = row['nonrept_long'] - row['nonrept_short']

        rep_date = row['report_date']
        wk = row['week_of_year']
        mo = rep_date.month

        time_series.append({
            'date': rep_date.isoformat(),
            'noncomm_net': nc_net,
            'comm_net': cm_net,
            'nonrept_net': nr_net,
            'open_interest': row['open_interest'],
        })

        wk_acc.setdefault(wk, []).append((nc_net, cm_net, nr_net))
        mo_acc.setdefault(mo, []).append((nc_net, cm_net, nr_net))

    def calc_avgs(acc):
        res = {}
        for key, vals in sorted(acc.items()):
            count = len(vals)
            res[key] = {
                'avg_noncomm_net': round(sum(v[0] for v in vals) / count),
                'avg_comm_net': round(sum(v[1] for v in vals) / count),
                'avg_nonrept_net': round(sum(v[2] for v in vals) / count),
                'count': count,
            }
        return res

    return {
        'time_series': time_series,
        'seasonality_weekly': calc_avgs(wk_acc),
        'seasonality_monthly': calc_avgs(mo_acc),
    }
